"""Prepare installers generated by stores or by Lutris for local setup programs.

A catalog keeps the scripts it found on the backend's side; frontends see
InstallerChoice metadata and refer to a script by the catalog's id and the
choice's id. Selecting a choice checks what installing with it involves, and
never runs the script.
"""

import asyncio
import copy
from collections import OrderedDict
from dataclasses import dataclass
from gettext import gettext as _
from pathlib import Path
from typing import TYPE_CHECKING, Any
from uuid import uuid4

from lutris import sysoptions
from lutris.api import parse_installer_url
from lutris.backend.models import InstallerCatalog, InstallerChoice, InstallerSelection
from lutris.database import games as games_db
from lutris.database.services import ServiceGameCollection
from lutris.exceptions import LutrisError
from lutris.installer import AUTO_WIN32_EXE
from lutris.installer import InstallationKind as InstallationKind
from lutris.installer.errors import MissingGameDependencyError
from lutris.installer.interpreter import ScriptInterpreter
from lutris.runners import get_runner_human_name, is_valid_runner_name
from lutris.services import SERVICES
from lutris.services.base import OnlineService
from lutris.util.log import logger
from lutris.util.strings import slugify

if TYPE_CHECKING:
    from lutris.services.base import BaseService

# How many catalogs are kept for frontends that never close theirs
_CATALOG_LIMIT = 8
_REQUIRED_FIELDS = ("name", "game_slug", "slug", "runner", "version", "script")

WINDOWS_SETUP_PRESETS = (
    (_("Windows 10"), "win10"),
    (_("Windows 11"), "win11"),
    (_("Windows 7"), "win7"),
)

type _Script = dict[str, Any]


@dataclass(frozen=True)
class _Origin:
    service: BaseService | None = None
    appid: str | None = None
    game_id: str = ""
    kind: InstallationKind = InstallationKind.INSTALL


@dataclass(frozen=True)
class _Catalog:
    scripts: dict[str, _Script]
    origin: _Origin


_catalogs: OrderedDict[str, _Catalog] = OrderedDict()


def can_install_game(installed: bool, service: str | None, appid: str | None) -> bool:
    return not installed and bool(service in SERVICES and appid)


def can_update_game(installed: bool, service: str | None, appid: str | None) -> bool:
    return installed and bool(appid and service in {"gog", "itchio"})


def can_install_dlc(installed: bool, service: str | None, appid: str | None) -> bool:
    return installed and bool(appid and service == "gog")


def get_store_install_target(uri: str) -> tuple[str, str] | None:
    """Read the source and app ID from an install URI, or pass through a launch URI."""
    try:
        request = parse_installer_url(uri)
    except ValueError as error:
        raise LutrisError(_("Invalid Lutris URI: %s") % uri) from error
    if request["action"] != "install" and not request["service"]:
        return None
    if request["service"] and request["appid"] and request["action"] in (None, "install"):
        return request["service"], request["appid"]
    raise LutrisError(_("Choose a game from one of your library sources to install."))


async def find_store_installers(
    service_id: str,
    appid: str,
    game_id: str = "",
    kind: InstallationKind = InstallationKind.INSTALL,
) -> InstallerCatalog:
    """Prepare choices for a game from a synced source."""
    scripts, origin = await asyncio.to_thread(_store_installers, service_id, appid, game_id, kind)
    return _catalog_from_scripts(scripts, origin)


def _store_installers(
    service_id: str, appid: str, game_id: str, kind: InstallationKind
) -> tuple[list[_Script], _Origin]:
    source_class = SERVICES.get(service_id)
    if not (source_class and appid):
        raise LutrisError(_("This game source is unavailable."))
    source = source_class()
    if isinstance(source, OnlineService) and not source.is_authenticated():
        raise LutrisError(_("Sign in to %s before installing this game.") % source.name)
    if kind != InstallationKind.INSTALL:
        row = _installed_game(game_id, service_id, appid)
        if kind == InstallationKind.UPDATE and can_update_game(True, service_id, appid):
            scripts = source.get_update_installers(row)
            if not scripts:
                raise LutrisError(_("No updates are available for this game."))
        elif kind == InstallationKind.DLC and can_install_dlc(True, service_id, appid):
            scripts = source.get_dlc_installers_runner(row, row["runner"])
            if not scripts:
                raise LutrisError(_("No installable DLC is available for this game."))
        else:
            raise LutrisError(_("This game source does not support that installation action."))
        return scripts, _Origin(source, appid, game_id, kind)

    row = ServiceGameCollection.get_game(service_id, appid)
    if row is None:
        raise LutrisError(_("Sync %s to find this game in your library.") % source.name)
    if games_db.get_games(filters={"service": service_id, "service_id": appid, "installed": 1}):
        raise LutrisError(_("This game is already installed."))
    return source.generate_installers(row), _Origin(source, appid)


def _installed_game(game_id: str, service_id: str, appid: str) -> games_db.DbGameDict:
    row = games_db.get_game_by_field(game_id, "id") if game_id else None
    if not row or not row["installed"] or row["service"] != service_id or str(row["service_id"]) != appid:
        raise LutrisError(_("This game must be installed from this source first."))
    if not row["directory"] or not Path(row["directory"]).is_dir():
        raise LutrisError(_("The installed game's folder could not be found."))
    return row


def windows_setup_locales() -> list[tuple[str, str]]:
    return sysoptions.get_locale_choices()


async def prepare_windows_setup(
    name: str, executable: str, windows_version: str = "win10", locale: str = ""
) -> InstallerCatalog:
    """Prepare Lutris' built-in installer for a Windows setup executable."""
    name = name.strip()
    path = Path(executable)
    slug = slugify(name)
    if not name or not slug:
        raise LutrisError(_("Enter a name for the game."))
    if not path.is_absolute() or path.suffix.lower() != ".exe" or not await asyncio.to_thread(path.is_file):
        raise LutrisError(_("Choose an existing Windows setup executable (.exe)."))
    if windows_version not in {value for _, value in WINDOWS_SETUP_PRESETS}:
        raise LutrisError(_("Choose a supported Windows version."))
    if locale not in {value for _, value in windows_setup_locales()}:
        raise LutrisError(_("Choose a supported locale."))

    tasks = [{"task": {"name": "wineexec", "executable": "$SETUP_EXE", "arch": "win64"}}]
    if windows_version != "win10":
        tasks.insert(0, {"task": {"name": "winetricks", "app": windows_version, "arch": "win64"}})
    plan: dict[str, Any] = {
        "game": {"exe": AUTO_WIN32_EXE, "prefix": "$GAMEDIR"},
        "variables": {"SETUP_EXE": str(path)},
        "installer": tasks,
    }
    if locale:
        plan["system"] = {"env": {"LC_ALL": locale}}
    return _catalog_from_scripts(
        [
            {
                "name": name,
                "version": _("Windows setup program"),
                "slug": f"{slug}-setup",
                "game_slug": slug,
                "runner": "wine",
                "script": plan,
            }
        ]
    )


def _catalog_from_scripts(scripts: list[_Script], origin: _Origin = _Origin()) -> InstallerCatalog:
    scripts = [script for script in scripts if _is_usable(script)]
    if not scripts:
        raise LutrisError(_("No installer available."))

    catalog_id = uuid4().hex
    by_choice = {str(index): script for index, script in enumerate(scripts)}
    _catalogs[catalog_id] = _Catalog(by_choice, origin)
    while len(_catalogs) > _CATALOG_LIMIT:
        _catalogs.popitem(last=False)
    return InstallerCatalog(
        id=catalog_id,
        game_name=scripts[0]["name"],
        game_slug=scripts[0]["game_slug"],
        choices=tuple(_to_choice(choice_id, script) for choice_id, script in by_choice.items()),
    )


async def close_catalog(catalog_id: str) -> None:
    """Forget a catalog's scripts once the frontend is done with it."""
    _catalogs.pop(catalog_id, None)


async def select_installer(catalog_id: str, choice_id: str) -> InstallerSelection:
    """Check a script can be used here, and say what installing with it involves."""
    script, origin = _copy_choice(catalog_id, choice_id)
    return await asyncio.to_thread(_check_script, catalog_id, choice_id, script, origin)


def _copy_choice(catalog_id: str, choice_id: str) -> tuple[_Script, _Origin]:
    try:
        catalog = _catalogs[catalog_id]
        script = catalog.scripts[choice_id]
    except KeyError as error:
        raise LutrisError(_("This installer is no longer available. Open the game's installers again.")) from error
    _catalogs.move_to_end(catalog_id)
    return copy.deepcopy(script), catalog.origin


async def build_interpreter(
    catalog_id: str, choice_id: str, delegate: ScriptInterpreter.InterpreterUIDelegate
) -> tuple[ScriptInterpreter, InstallationKind]:
    """Build a fresh interpreter on a copy of the selected installation plan."""
    script, origin = _copy_choice(catalog_id, choice_id)
    interpreter = await asyncio.to_thread(_build_interpreter, script, origin, delegate)
    return interpreter, origin.kind


def _build_interpreter(
    script: _Script, origin: _Origin, delegate: ScriptInterpreter.InterpreterUIDelegate
) -> ScriptInterpreter:
    delegate.service = origin.service
    delegate.appid = origin.appid
    if origin.service and origin.appid:
        if isinstance(origin.service, OnlineService) and not origin.service.is_authenticated():
            raise LutrisError(_("Sign in to %s before installing this game.") % origin.service.name)
        if origin.kind == InstallationKind.INSTALL:
            if games_db.get_games(filters={"service": origin.service.id, "service_id": origin.appid, "installed": 1}):
                raise LutrisError(_("This game is already installed."))
        else:
            delegate.installed_game = _installed_game(origin.game_id, str(origin.service.id), origin.appid)
    interpreter = ScriptInterpreter(script, delegate)
    if origin.service and origin.service.local:
        interpreter.target_path = origin.service.get_game_directory(script)
    return interpreter


def _is_usable(script: _Script) -> bool:
    missing = [field for field in _REQUIRED_FIELDS if not script.get(field)]
    if missing:
        logger.warning("Skipping install script %s, missing %s", script.get("slug"), ", ".join(missing))
        return False
    if not is_valid_runner_name(script["runner"]):
        logger.warning("Skipping install script %s for unsupported runner %s", script["slug"], script["runner"])
        return False
    if not isinstance(script["script"], dict):
        logger.warning("Skipping install script %s, its script isn't a mapping", script["slug"])
        return False
    files = script["script"].get("files") or []
    if not isinstance(files, list) or any(not isinstance(file, dict) or len(file) != 1 for file in files):
        logger.warning("Skipping install script %s, its files are malformed", script["slug"])
        return False
    return True


def _text(script: _Script, key: str) -> str:
    value = script.get(key)
    return str(value).strip() if value else ""


def _to_choice(choice_id: str, script: _Script) -> InstallerChoice:
    return InstallerChoice(
        id=choice_id,
        version=script["version"],
        runner=script["runner"],
        runner_name=get_runner_human_name(script["runner"]),
        description=_text(script, "description"),
        notes=_text(script, "notes"),
        credits=_text(script, "credits"),
    )


def _check_script(catalog_id: str, choice_id: str, script: _Script, origin: _Origin) -> InstallerSelection:
    try:
        interpreter = _build_interpreter(script, origin, ScriptInterpreter.InterpreterUIDelegate())
    except MissingGameDependencyError as error:
        return InstallerSelection(
            catalog_id=catalog_id,
            choice_id=choice_id,
            game_name=script["name"],
            version=script["version"],
            creates_game_folder=False,
            default_directory="",
            runners_to_install=(),
            required_game_slug=error.slug,
        )
    installer = interpreter.installer
    runners = interpreter.get_runners_to_install()
    return InstallerSelection(
        catalog_id=catalog_id,
        choice_id=choice_id,
        game_name=installer.game_name,
        version=installer.version,
        creates_game_folder=installer.creates_game_folder,
        default_directory=interpreter.target_path or "",
        runners_to_install=tuple(runner.human_name for runner in runners),
    )
